const j = $input.first().json;
const body = String(j.text_body || '').slice(0, 8000);
const BUSINESS_TZ = 'Asia/Kolkata';
const receivedDate = new Date(j.received_at);
const received_local = Number.isNaN(receivedDate.getTime()) ? String(j.received_at || '') : receivedDate.toLocaleString('en-GB', { timeZone: BUSINESS_TZ, weekday: 'long', day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }) + ' (' + BUSINESS_TZ + ', UTC+05:30)';
return [{ json: {
  correlation_id: j.correlation_id,
  idempotency_key: j.idempotency_key,
  email_event_id: j.email_event_id || '',
  mailbox: j.mailbox,
  message_id: j.message_id,
  thread_id: j.thread_id || null,
  from_name: j.from_name,
  from_email: j.from_email,
  subject: j.subject,
  received_at: j.received_at,
  received_local,
  source_link: j.source_link || null,
  rules: j.rules || {},
  prompt_body: body,
  prompt_input: { from: j.from_name + ' <' + j.from_email + '>', subject: j.subject, body }
}}];

const email = $('Prepare AI Input').item.json;
const raw = $input.first().json;
const aiOut = raw.output || raw;
const threshold = 0.70;
let review_required = false;
let reason = '';
let triage = {
  category: '', importance: '', needs_reply: false, needs_task: false,
  summary: '', draft_reply: '', suggested_due_at: null,
  confidence: NaN, sensitive: false, safety_reason: null
};
if (raw.error || !aiOut || typeof aiOut !== 'object') {
  review_required = true; reason = 'llm_timeout_or_malformed';
} else {
  triage = {
    category: String(aiOut.category || ''),
    importance: String(aiOut.importance || ''),
    needs_reply: !!aiOut.needs_reply,
    needs_task: !!aiOut.needs_task,
    summary: String(aiOut.summary || ''),
    draft_reply: String(aiOut.draft_reply || ''),
    suggested_due_at: aiOut.suggested_due_at || null,
    confidence: Number(aiOut.confidence),
    sensitive: !!aiOut.sensitive,
    safety_reason: aiOut.safety_reason || null
  };
  const conf = triage.confidence;
  if (!triage.category || typeof conf !== 'number' || isNaN(conf)) { review_required = true; reason = 'malformed_output'; }
  else if (conf < threshold) { review_required = true; reason = 'low_confidence'; }
  else if (triage.sensitive) { review_required = true; reason = 'sensitive_content'; }
}
// Deterministic due-date check in the business timezone (P2-E2E-013).
const BUSINESS_TZ = 'Asia/Kolkata';
const BUSINESS_OFFSET = '+05:30';
let due_date_check = triage.suggested_due_at ? 'ok' : 'none';
if (triage.suggested_due_at) {
  const due = new Date(triage.suggested_due_at);
  const received = new Date(email.received_at);
  const dueText = (String(email.subject || '') + '\n' + String(email.prompt_body || '')).toLowerCase();
  const mentioned = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'].filter(d => dueText.includes(d));
  const parts = Number.isNaN(due.getTime()) ? null : Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: BUSINESS_TZ, weekday: 'long', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(due).map(p => [p.type, p.value]));
  if (!parts) due_date_check = 'dropped_unparseable';
  else if (!Number.isNaN(received.getTime()) && due < received) due_date_check = 'dropped_before_received';
  else if (mentioned.length && !mentioned.includes(parts.weekday.toLowerCase())) due_date_check = 'dropped_weekday_mismatch';
  triage.suggested_due_at = due_date_check === 'ok' ? parts.year + '-' + parts.month + '-' + parts.day + 'T' + parts.hour + ':' + parts.minute + ':' + parts.second + BUSINESS_OFFSET : null;
}
return [{ json: { ...email, ...triage, review_required, gate_reason: reason, threshold, due_date_check } }];

const e = $('Prepare AI Input').item.json;
const g = $('Confidence & Safety Gate').item.json;
const rec = $('Write Review Queue').first().json || {};
return [{ json: {
  correlation_id: e.correlation_id,
  idempotency_key: e.idempotency_key,
  email_event_id: e.email_event_id,
  review_required: true,
  gate_reason: g.gate_reason,
  category: g.category, importance: g.importance,
  needs_reply: g.needs_reply, needs_task: g.needs_task,
  summary: g.summary, draft_reply: g.draft_reply,
  suggested_due_at: g.suggested_due_at, due_date_check: g.due_date_check, confidence: g.confidence,
  sensitive: g.sensitive, safety_reason: g.safety_reason,
  review_queue_id: rec.id || ''
}}];
